def name_operands(region,function_address,operation):
    if (region,function_address)!=('Action',0xF138):return operation
    for offset,name in ((10,'StateCode'),(11,'LinkedIndex'),(17,'Unknown11'),(18,'ClassCode'),(19,'EffectReserve'),
                        (20,'MissileRepeatDelay'),(22,'SavedStateCode'),(24,'ReuseByte')):
        operation=operation.replace('(IX+#'+format(offset,'02X')+')','(IX + @FActionRecord.'+name+')')
    for address,name in ((0xEA15,'CheckCandidateListReady'),(0xE9C2,'FindNearestListedRecord'),(0x64DF,'DispatchRecordClass'),
                         (0xE863,'SpawnClass9ForClass8'),(0x6417,'CreateCargoAndUpdateList'),(0xE761,'PrepareLinkedRecordContext'),
                         (0xE794,'LoadLinkedRecordVectors'),(0x624B,'CheckLinkedDistanceAndStepCodes'),(0xEB72,'NextRandomWord0'),
                         (0xE804,'CheckAndToggleLinkedOverlay'),(0xF222,'CheckMissileSpawnWindow'),(0xF24F,'CreateMissileAndContinueOffsets'),
                         (0xF6BD,'AcquireLinkAndApplyOffsets'),(0xF0F8,'PrepareObjectOffsetTransform')):
        operation=operation.replace('#'+format(address,'04X'),'@Action.'+name+'.Entry')
    for index,address in enumerate((0xAF48,0xAF56,0xAF69)):
        operation=operation.replace('(#'+format(address,'04X')+')','(@ActionPatchedVectorState.Input'+str(index)+')')
    return operation.replace('#EF50','@ActionObjectStateHandlers.State00')
